#include <stdio.h>
int main(void){int key,counter,n,i,p,stream,c;printf("Enter 10-bit S-DES key (0-1023): ");scanf("%d",&key);printf("Starting 8-bit counter (0-255): ");scanf("%d",&counter);printf("Number of bytes: ");scanf("%d",&n);if(key<0||key>1023||counter<0||counter>255||n<1||n>100)return puts("Invalid input."),1;puts("CTR demonstration uses a deterministic educational keystream (counter XOR key low byte).");for(i=0;i<n;i++){printf("Plaintext byte (0-255): ");scanf("%d",&p);if(p<0||p>255)return puts("Invalid byte."),1;stream=(counter+i)^(key&255);c=p^stream;printf("Counter %d -> ciphertext %d (0x%02X)\n",(counter+i)&255,c&255,c&255);}return 0;}